```json
{
  "root_causes": [
    {
      "service": "search",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {
          "kind": "metric",
          "sql": "SELECT service_name, attr_k8s_deployment_name, metric, min(value) mn, max(value) mx, count(*) n FROM abnormal_metrics WHERE service_name='search' AND metric='k8s.deployment.available' GROUP BY 1,2,3",
          "claim": "Search deployment available is 0 for every abnormal sample, while normal samples are 1."
        },
        {
          "kind": "metric",
          "sql": "SELECT 'norm_search_metrics' src, max(time) last_seen, count(*) n FROM normal_metrics WHERE attr_k8s_pod_name='search-57484cf6d8-wjbxh' UNION ALL SELECT 'abn_search_pod_metrics', max(time), count(*) FROM abnormal_metrics WHERE attr_k8s_pod_name LIKE 'search%'",
          "claim": "The search pod reports metrics until 03:15:29 in normal and has no pod-level metrics in the abnormal period."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_status_code, count(*) n, round(avg(duration)/1e6,2) avg_ms FROM abnormal_traces WHERE span_name LIKE 'search.Search%' GROUP BY 1,2,3",
          "claim": "Frontend's search.Search/Nearby client spans fail with Error in about 0.02 ms, 1136 times; no search server spans exist in abnormal."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "search",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_status_code st, attr_http_response_status_code code, count(*) n, round(avg(duration)/1e6,2) avg_ms FROM abnormal_traces WHERE service_name='frontend' AND attr_span_kind='Server' AND span_name='HTTP /hotels' GROUP BY 1,2,3,4",
          "claim": "Frontend /hotels server spans return HTTP 500 in about 0.12 ms, 1136 times, versus normal 200 responses averaging 6.6 ms."
        }
      ]
    }
  ]
}
```

